#!/usr/bin/env bash
# Read-only topology checks. This script does NOT establish ICMP/TCP reachability.
set -euo pipefail
export AWS_DEFAULT_REGION="${AWS_REGION:-${AWS_DEFAULT_REGION:-us-east-1}}"
ENV_FILE="${NETWORKING_ENV_FILE:-/tmp/networking_ids.env}"
[[ -r "$ENV_FILE" ]] || { echo "Missing $ENV_FILE: run vpc_peering.sh first." >&2; exit 1; }
# File is generated by our own local lab script. Never source untrusted files.
# shellcheck disable=SC1090
source "$ENV_FILE"
: "${VPC_A:?}" "${VPC_B:?}" "${PEERING_ID:?}" "${RT_A_PRIV:?}"

echo "Account / region:"
aws sts get-caller-identity --query '[Account,Arn]' --output table
aws configure get region || true
echo "Peering status:"
aws ec2 describe-vpc-peering-connections   --vpc-peering-connection-ids "$PEERING_ID"   --query 'VpcPeeringConnections[0].[Status.Code,RequesterVpcInfo.CidrBlock,AccepterVpcInfo.CidrBlock]'   --output table
echo "Route tables in each VPC:"
aws ec2 describe-route-tables   --filters Name=vpc-id,Values="$VPC_A","$VPC_B"   --query 'RouteTables[*].[RouteTableId,VpcId,Routes[*].DestinationCidrBlock]'   --output json
echo "Subnets:"
aws ec2 describe-subnets   --filters Name=vpc-id,Values="$VPC_A","$VPC_B"   --query 'Subnets[*].[SubnetId,VpcId,CidrBlock,AvailabilityZone]'   --output table
echo "Read-only checks completed. To test connectivity, launch authorized test hosts"
echo "and verify packets, route tables, security groups and NACLs from both sides."
